<?php
declare(strict_types=1);date_default_timezone_set('Africa/Nairobi');
$rates=['single'=>3500,'double'=>5000,'family'=>7500];$caps=['single'=>1,'double'=>2,'family'=>4];$labels=['single'=>'Single Room','double'=>'Double Room','family'=>'Family Room'];
function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function val(string $k):string{$v=$_POST[$k]??'';return is_string($v)?trim($v):'';}
if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Please submit the booking form.');}
$name=val('full_name');$id=val('identity');$email=val('email');$phone=val('phone');$date=val('checkin');$room=val('room_type');$n=filter_var($_POST['nights']??null,FILTER_VALIDATE_INT);$g=filter_var($_POST['guests']??null,FILTER_VALIDATE_INT);
$b=isset($_POST['breakfast'])&&$_POST['breakfast']==='1';$t=isset($_POST['transfer'])&&$_POST['transfer']==='1';$l=isset($_POST['late_checkout'])&&$_POST['late_checkout']==='1';$errors=[];
if($name===''||strlen($name)>200)$errors[]='Enter your name.';if($id===''||strlen($id)>40)$errors[]='Enter an ID or passport number.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(!preg_match('/^\d{10}$/',$phone))$errors[]='Phone must contain exactly 10 digits.';
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$errors[]='Choose a valid check-in date.';else{$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date||$dt<new DateTimeImmutable('today'))$errors[]='Check-in must be today or later.';}
if(!$n||$n<1||$n>14)$errors[]='Nights must be 1–14.';if(!$g||$g<1)$errors[]='At least one guest is required.';if(!isset($rates[$room]))$errors[]='Select a room.';elseif($g&&$g>$caps[$room])$errors[]=$labels[$room].' capacity is '.$caps[$room].'.';
if($errors){http_response_code(422);$title='Please review your details';}else{$total=$rates[$room]*$n+($b?700*$g*$n:0)+($t?2000:0)+($l?2000:0);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sunrise Hotel confirmation</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">◉ SUNRISE <small>HOTEL · MOMBASA</small></a><nav><a href="index.html">Home</a><a href="booking.html">Rooms & booking</a></nav></header><main class="result"><article><p class="eyebrow dark">— SUNRISE HOTEL · MOMBASA</p><?php if($errors): ?><div class="badge err">!</div><h1><?= h($title) ?></h1><ul class="errors"><?php foreach($errors as $e): ?><li><?= h($e) ?></li><?php endforeach; ?></ul><a class="btn" href="booking.html">Back to booking</a><?php else: ?><div class="badge">✓</div><h1>Booking <em>received.</em></h1><p>Thank you, <?= h($name) ?>. We can't wait to welcome you.</p><div class="receipt"><?php foreach([['GUEST',$name],['ID / PASSPORT',$id],['EMAIL',$email],['PHONE',$phone],['CHECK-IN',$date],['ROOM',$labels[$room]],['GUESTS · NIGHTS',"$g · $n nights"],['BREAKFAST',$b?'Yes':'No'],['AIRPORT TRANSFER',$t?'Yes':'No'],['LATE CHECKOUT · REQUIREMENT 9',$l?'Yes · KSh 2,000':'No']] as [$key,$value]): ?><div><span><?= h($key) ?></span><b><?= h($value) ?></b></div><?php endforeach; ?><div class="grand"><span>TOTAL AMOUNT</span><b>KSh <?= number_format($total) ?></b></div></div><small class="footnote">PHP independently calculated this amount using server-side prices.</small><?php endif; ?></article></main><footer><b>SUNRISE HOTEL</b><span>INDIAN OCEAN COAST · KENYA</span><span>© 2026 SUNRISE HOTEL</span></footer></body></html>
